create view public.world_ai_completed_responses with(security_invoker=true) as select receipt,received_at,consented_at,survey_version,duration_seconds,answer_count,responses,answer_atlas,route,indices,result_title from public.world_ai_responses where not is_test; revoke all on public.world_ai_completed_responses from public,anon,authenticated; grant select on public.world_ai_completed_responses to service_role;
